"""Latest interactive invocation owns each pane until explicitly superseded."""
import math
from pathlib import Path
from typing import Callable, Optional
from uuid import uuid4

from . import store, transcripts
from .models import Pane, Paths, Registration, Session


def normalize_terminal(terminal: str) -> str:
    if not isinstance(terminal, str):
        raise ValueError("expected terminal UUID")
    return transcripts.normalize_uuid(terminal.rsplit(":", 1)[-1])


def _session_dict(session: Optional[Session]) -> Optional[dict]:
    if session is None:
        return None
    return {"session_id": session.session_id, "cwd": str(session.cwd),
            "transcript": str(session.transcript), "codex_home": str(session.codex_home)}


def _encode(reg: Registration) -> dict:
    return {"token": reg.token, "terminal": reg.terminal, "shell_pid": reg.shell_pid,
            "shell_started": reg.shell_started, "started_at": reg.started_at,
            "launch": reg.launch, "active": reg.active,
            "session": _session_dict(reg.session), "request": reg.request}


def _required_string(value: object) -> str:
    if not isinstance(value, str) or not value:
        raise ValueError("expected nonempty string")
    return value


def _decode(value: dict, paths: Paths) -> Registration:
    if not isinstance(value, dict):
        raise ValueError("invalid registration")
    try:
        token = transcripts.normalize_uuid(value["token"])
        terminal = normalize_terminal(value["terminal"])
        pid = value["shell_pid"]
        if type(pid) is not int or pid <= 0:
            raise ValueError("invalid shell PID")
        started = _required_string(value["shell_started"])
        timestamp = value["started_at"]
        if type(timestamp) not in (int, float) or not math.isfinite(timestamp):
            raise ValueError("invalid registration timestamp")
        launch = _required_string(value["launch"])
        if type(value["active"]) is not bool:
            raise ValueError("invalid active state")
        request = value["request"]
        if request is not None:
            _required_string(request)
        raw_session = value["session"]
        session = None
        if raw_session is not None:
            sid = transcripts.normalize_uuid(raw_session["session_id"])
            cwd, transcript, home = [Path(_required_string(raw_session[key]))
                                     for key in ("cwd", "transcript", "codex_home")]
            if not all(path.is_absolute() for path in (cwd, transcript, home)) or home != paths.codex_home:
                raise ValueError("invalid session paths")
            session = Session(sid, cwd, transcript, home)
        return Registration(token, terminal, pid, started, float(timestamp), launch,
                            value["active"], session, request)
    except (KeyError, TypeError, AttributeError) as exc:
        raise ValueError("invalid registration schema") from exc


def _load(paths: Paths) -> list[Registration]:
    state = store.read(paths, "registry.json")
    if state is None:
        return []
    if not isinstance(state.get("registrations"), list):
        raise ValueError("invalid registry schema")
    entries = [_decode(item, paths) for item in state["registrations"]]
    if len({reg.terminal for reg in entries}) != len(entries):
        raise ValueError("duplicate pane owners")
    return entries


def _save(paths: Paths, entries: list[Registration]) -> None:
    store.write(paths, "registry.json", {"version": 1, "registrations": [_encode(reg) for reg in entries]})


def _owns_request(reg: Registration, entry: dict) -> bool:
    return (reg.request == entry["request"] and reg.terminal == entry["target"]
            and reg.launch == entry["launch"])


def register(paths: Paths, terminal: str, shell_pid: int, shell_started: str,
             launch: str, now: float, request: Optional[str] = None) -> Registration:
    reg = Registration(str(uuid4()), normalize_terminal(terminal), shell_pid,
                       shell_started, now, launch, True, None, request)
    # Use the same validation for newly created and persisted records.
    reg = _decode(_encode(reg), paths)
    with store.lock(paths, "state.lock"):
        old_entries = _load(paths)
        pending = store.pending(paths)
        pending = [entry for entry in pending if entry["request"] == request
                   or not any(old.terminal == reg.terminal and _owns_request(old, entry)
                              for old in old_entries)]
        for entry in pending:
            if (entry["request"] == request and entry["target"] == reg.terminal
                    and entry["launch"] == launch and entry["status"] in ("reserved", "sent")):
                value = entry["session"]
                session = transcripts.validate(Path(value["transcript"]), value["session_id"],
                                               paths.codex_home, Path(value["cwd"]))
                if session is not None and session.cwd.is_dir():
                    reg.session = session
                    entry["status"] = "acknowledged"
                    entry["token"] = reg.token
        if pending or (paths.state_dir / "pending.json").exists():
            store.save_pending(paths, pending)
        entries = [old for old in old_entries if old.terminal != reg.terminal]
        entries.append(reg)
        _save(paths, entries)
    return reg


def finish(paths: Paths, token: str) -> None:
    with store.lock(paths, "state.lock"):
        entries = _load(paths)
        for reg in entries:
            if reg.token == token:
                reg.active = False
                _save(paths, entries)
                pending = store.pending(paths)
                remaining = [entry for entry in pending if not _owns_request(reg, entry)]
                if remaining != pending:
                    store.save_pending(paths, remaining)
                break


def accept_event(paths: Paths, token: str, terminal: str, event: dict,
                 identity: Callable[[int], Optional[str]], now: float) -> bool:
    if not isinstance(event, dict) or event.get("hook_event_name") not in ("SessionStart", "UserPromptSubmit", "Stop"):
        return False
    try:
        terminal = normalize_terminal(terminal)
        session = transcripts.validate(Path(event["transcript_path"]), event["session_id"],
                                       paths.codex_home, Path(event["cwd"]))
    except (KeyError, ValueError, TypeError):
        return False
    if session is None:
        return False
    with store.lock(paths, "state.lock"):
        entries = _load(paths)
        for reg in entries:
            if reg.token != token or reg.terminal != terminal or not reg.active:
                continue
            if identity(reg.shell_pid) != reg.shell_started or now < reg.started_at:
                return False
            if reg.session is not None and reg.session.session_id != session.session_id:
                return False
            reg.session = session
            _save(paths, entries)
            return True
    return False


def live(paths: Paths, panes: list[Pane], identity: Callable[[int], Optional[str]]) -> list[Registration]:
    terminals = {normalize_terminal(pane.terminal) for pane in panes}
    with store.lock(paths, "state.lock"):
        return [reg for reg in _load(paths)
                if reg.active and reg.session is not None and reg.terminal in terminals
                and identity(reg.shell_pid) == reg.shell_started]

"""Select a previous launch and coordinate explicitly reserved resume requests."""
from pathlib import Path
import re
import shlex
import sys
import time
import unicodedata
from typing import Optional
from uuid import uuid4

from . import registry, snapshots, store, transcripts
from .iterm import ITerm, UnknownTabOutcome
from .models import Choice, FirstResume, Paths, Session


def _prune(paths, entries, panes, launch):
    terminals = {registry.normalize_terminal(pane.terminal) for pane in panes}
    return [entry for entry in entries if entry["launch"] == launch
            and (entry["target"] or entry["source"]) in terminals]


def _claim(paths, current, previous, processed=False):
    state = store.read(paths, "auto.json") or {"version": 1, "claims": []}
    claims = state.get("claims")
    if (not isinstance(claims, list) or any(not isinstance(claim, list) or len(claim) != 2
            or any(not isinstance(value, str) or not value for value in claim) for claim in claims)):
        raise ValueError("invalid auto claims")
    key = [current, previous]
    available = not any(claim[0] == current or claim[1] == previous for claim in claims)
    if (available or processed) and key not in claims:
        store.write(paths, "auto.json", {"version": 1, "claims": claims + [key]})
    return available


def choices(paths: Paths, client: ITerm, auto: bool, now: float) -> tuple[list[Choice], list[str]]:
    with store.lock(paths, "state.lock"):
        before_inventory = store.pending(paths)
    launch, panes = client.launch_id(), client.panes()
    snapshot = snapshots.candidate(paths, launch)
    if snapshot is None:
        return [], []
    opened = {reg.session.session_id for reg in registry.live(paths, panes, client.identity)}
    with store.lock(paths, "state.lock"):
        pending = store.pending(paths)
        # A coordinator may create a target after this inventory was observed.
        # Only unchanged reservations can be cleaned using that observation.
        remaining = _prune(paths, pending, panes, launch) if pending == before_inventory else pending
        if pending != remaining:
            store.save_pending(paths, remaining)
        opened.update(entry["session"]["session_id"] for entry in remaining)
        if auto and not _claim(paths, launch, snapshot.launch):
            return [], []
    result, notes, seen = [], [], set()
    for tab in snapshot.tabs:
        session = tab.session
        if session.session_id in opened or session.session_id in seen:
            continue
        seen.add(session.session_id)
        validated = transcripts.validate(session.transcript, session.session_id, paths.codex_home, session.cwd)
        if validated is None or not validated.cwd.is_dir():
            notes.append("Пропущена недоступная сессия " + session.session_id)
            continue
        try:
            minutes = max(0, int((now - validated.transcript.stat().st_mtime) // 60))
        except OSError:
            notes.append("Пропущен недоступный журнал " + session.session_id)
            continue
        age = "%s мин" % minutes if minutes < 60 else "%s ч" % (minutes // 60) if minutes < 1440 else "%s д" % (minutes // 1440)
        result.append(Choice(tab.order, validated, transcripts.title(validated), age))
    return result, notes


def _visible(value):
    value = re.sub(r"\x1b(?:\[[0-?]*[ -/]*[@-~]|\][^\x07\x1b]*(?:\x07|\x1b\\))", "", value)
    return " ".join("".join(character if not unicodedata.category(character).startswith("C") else " "
                             for character in value).split())


def rows(choices: list[Choice]) -> list[str]:
    return ["\t".join([str(index), transcripts.normalize_uuid(choice.session.session_id),
                       "%s.%s" % choice.order, _visible(choice.title),
                       _visible(choice.session.cwd.name), _visible(choice.age)])
            for index, choice in enumerate(choices, 1)]


def command(session: Session, request: str, cache_root: Path) -> str:
    sid, request = transcripts.normalize_uuid(session.session_id), transcripts.normalize_uuid(request)
    return "cd -- %s && CODEX_HOME=%s CODEX_RESTORE_CACHE_DIR=%s CODEX_RESTORE_REQUEST=%s codex resume %s" % (
        shlex.quote(str(session.cwd)), shlex.quote(str(session.codex_home)), shlex.quote(str(cache_root)),
        shlex.quote(request), shlex.quote(sid))


def cancel(paths: Paths, request: str) -> None:
    request = transcripts.normalize_uuid(request)
    with store.lock(paths, "state.lock"):
        pending = store.pending(paths)
        remaining = [entry for entry in pending if entry["request"] != request or entry["status"] != "reserved"]
        if remaining != pending:
            store.save_pending(paths, remaining)


def _update(paths, request, target, status):
    with store.lock(paths, "state.lock"):
        entries = store.pending(paths)
        for entry in entries:
            if entry["request"] == request and entry["status"] != "acknowledged":
                entry.update(target=target, status=status)
        store.save_pending(paths, entries)


def _acknowledged(paths, request):
    with store.lock(paths, "state.lock"):
        return any(entry["request"] == request and entry["status"] == "acknowledged"
                   for entry in store.pending(paths))


def prepare(paths: Paths, client: ITerm, selected_ids: list[str], caller_terminal: str,
            now: float) -> Optional[FirstResume]:
    if not selected_ids:
        return None
    selected = [transcripts.normalize_uuid(sid) for sid in selected_ids]
    if len(set(selected)) != len(selected):
        raise ValueError("duplicate selected UUID")
    caller = registry.normalize_terminal(caller_terminal)
    with store.lock(paths, "restore.lock"):
        launch = client.launch_id()
        panes = client.panes()
        sources = [pane for pane in panes if registry.normalize_terminal(pane.terminal) == caller]
        if len(sources) != 1:
            raise ValueError("Не найдено окно исходной панели iTerm2")
        snapshot = snapshots.candidate(paths, launch)
        if snapshot is None:
            return None
        known = {tab.session.session_id for tab in snapshot.tabs}
        if not set(selected).issubset(known):
            raise ValueError("selected UUID is absent from the snapshot")
        available, notes = choices(paths, client, False, now)
        for note in notes:
            print(note, file=sys.stderr)
        chosen = [choice.session for choice in available if choice.session.session_id in selected]
        if not chosen:
            return None
        if client.launch_id() != launch:
            raise ValueError("iTerm2 launch changed")
        with store.lock(paths, "state.lock"):
            pending = store.pending(paths)
            # Registry's public live() owns this lock. Read its wire under the
            # already held lock to make the final check and reservation atomic.
            terminals = {registry.normalize_terminal(pane.terminal) for pane in panes}
            busy = {reg.session.session_id for reg in registry._load(paths)
                    if reg.active and reg.session is not None and reg.terminal in terminals
                    and client.identity(reg.shell_pid) == reg.shell_started}
            busy.update(entry["session"]["session_id"] for entry in pending)
            chosen = [session for session in chosen if session.session_id not in busy]
            if not chosen:
                return None
            reservations = [{"request": str(uuid4()), "session": registry._session_dict(session),
                             "source": caller, "target": caller if index == 0 else None,
                             "launch": launch, "status": "reserved"}
                            for index, session in enumerate(chosen)]
            store.save_pending(paths, pending + reservations)
            _claim(paths, launch, snapshot.launch, processed=True)
        try:
            for session, entry in zip(chosen[1:], reservations[1:]):
                request = entry["request"]
                try:
                    target = client.new_tab(sources[0].window_id)
                except UnknownTabOutcome:
                    # Retain source-bound reservation: never create another tab
                    # automatically after a request whose outcome is unknown.
                    print("Исход открытия неизвестен: %s. Проверьте вкладки iTerm2; автоматический повтор запрещён." % session.session_id, file=sys.stderr)
                    continue
                except Exception as exc:
                    cancel(paths, request)
                    print("Не удалось открыть вкладку %s: %s. Вручную: %s" % (
                        session.session_id, exc, command(session, request, paths.state_dir.parent)), file=sys.stderr)
                    continue
                # Persist before sending: even a lost reply cannot cause a duplicate launch.
                _update(paths, request, registry.normalize_terminal(target), "sent")
                try:
                    client.run(target, command(session, request, paths.state_dir.parent))
                except Exception:
                    pass
                deadline = time.monotonic() + 3.0
                while not _acknowledged(paths, request) and time.monotonic() < deadline:
                    time.sleep(min(0.1, max(0, deadline - time.monotonic())))
                if not _acknowledged(paths, request):
                    print("Запуск не подтверждён: %s. Проверьте вкладку; вручную: %s" % (
                        session.session_id, command(session, request, paths.state_dir.parent)), file=sys.stderr)
        finally:
            try:
                client.focus(caller)
            except Exception as exc:
                print("Не удалось вернуть фокус: %s" % exc, file=sys.stderr)
        return FirstResume(reservations[0]["request"], chosen[0])

"""Publish only complete inventories built from an unchanged registry version."""
import math
from pathlib import Path
from typing import Optional

from . import registry, store, transcripts
from .iterm import ITerm
from .models import Paths, SavedTab, Session, Snapshot


def _encode(snapshot: Snapshot) -> dict:
    return {"version": snapshot.version, "launch": snapshot.launch, "saved_at": snapshot.saved_at,
            "tabs": [{"order": list(tab.order), "session": {
                "session_id": tab.session.session_id, "cwd": str(tab.session.cwd),
                "transcript": str(tab.session.transcript), "codex_home": str(tab.session.codex_home)}}
                     for tab in snapshot.tabs]}


def _decode(value: dict, paths: Paths) -> Snapshot:
    try:
        launch, timestamp, tabs = value["launch"], value["saved_at"], value["tabs"]
        if (not isinstance(launch, str) or not launch or type(timestamp) not in (int, float)
                or not math.isfinite(timestamp) or not isinstance(tabs, list)):
            raise ValueError("invalid snapshot metadata")
        result = []
        for tab in tabs:
            order, session = tab["order"], tab["session"]
            if (not isinstance(order, list) or len(order) != 2
                    or any(type(number) is not int or number < 1 for number in order)):
                raise ValueError("invalid tab order")
            sid = transcripts.normalize_uuid(session["session_id"])
            directories = [Path(session[key]) for key in ("cwd", "transcript", "codex_home")]
            if not all(directory.is_absolute() for directory in directories) or directories[2] != paths.codex_home:
                raise ValueError("invalid snapshot paths")
            result.append(SavedTab(tuple(order), Session(sid, *directories)))
        if [tab.order for tab in result] != sorted({tab.order for tab in result}):
            raise ValueError("duplicate or unordered tabs")
        return Snapshot(launch, float(timestamp), result)
    except (KeyError, TypeError, AttributeError) as exc:
        raise ValueError("invalid snapshot schema") from exc


def capture(paths: Paths, client: ITerm, now: float,
            required_terminal: Optional[str] = None,
            required_token: Optional[str] = None) -> bool:
    """A hook requires its source registration to remain a live pane owner."""
    try:
        if type(now) not in (int, float) or not math.isfinite(now):
            return False
        launch = client.launch_id()
        if not launch:
            return False
        panes = client.panes()
        if required_terminal is not None and registry.normalize_terminal(required_terminal) not in {
                registry.normalize_terminal(pane.terminal) for pane in panes}:
            return False
        with store.lock(paths, "state.lock"):
            version = (paths.state_dir / "registry.json").read_bytes()
        owners = registry.live(paths, panes, client.identity)
        if required_terminal is not None or required_token is not None:
            if not any(owner.launch == launch
                       and (required_terminal is None or owner.terminal == registry.normalize_terminal(required_terminal))
                       and (required_token is None or owner.token == required_token)
                       for owner in owners):
                return False
        leaders = {}
        positions = {registry.normalize_terminal(pane.terminal): pane for pane in panes}
        for owner in owners:
            if owner.launch != launch:
                continue
            pane = positions[owner.terminal]
            key = (pane.window_no, pane.tab_no)
            if key not in leaders or owner.started_at < leaders[key].started_at:
                leaders[key] = owner
        snapshot = Snapshot(launch, now, [SavedTab(order, leaders[order].session)
                                         for order in sorted(leaders)])
        if client.launch_id() != launch:
            return False
        with store.lock(paths, "state.lock"):
            # No public registry API may be called while this lock is held.
            if (paths.state_dir / "registry.json").read_bytes() != version:
                return False
            current = store.read(paths, "tabs.json")
            if current is not None:
                old = _decode(current, paths)
                if old.saved_at > now:
                    return False
                if old.launch != launch:
                    store.write(paths, "tabs-prev.json", current)
            store.write(paths, "tabs.json", _encode(snapshot))
        return True
    except Exception:
        # A broken external adapter must never destroy the last good snapshot.
        return False


def candidate(paths: Paths, current_launch: str) -> Optional[Snapshot]:
    for name in ("tabs.json", "tabs-prev.json"):
        try:
            value = store.read(paths, name)
            if value is not None:
                snapshot = _decode(value, paths)
                if snapshot.launch != current_launch:
                    return snapshot
        except (OSError, ValueError, TypeError):
            continue
    return None

"""Private, atomic state files; callers serialize their own versioned schemas."""
from contextlib import contextmanager
import fcntl
import hashlib
import json
import os
from pathlib import Path
import tempfile
import time
from typing import Optional

from .models import Paths
from . import transcripts


def paths(codex_home: Path, cache_root: Path) -> Paths:
    home = codex_home.expanduser().resolve()
    partition = hashlib.sha256(os.fsencode(home)).hexdigest()
    return Paths(home, cache_root.expanduser().resolve() / partition)


def _directory(paths: Paths) -> None:
    paths.state_dir.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    paths.state_dir.parent.chmod(0o700)
    paths.state_dir.mkdir(mode=0o700, exist_ok=True)
    paths.state_dir.chmod(0o700)


def _file(paths: Paths, name: str) -> Path:
    if not name or Path(name).name != name or name in (".", ".."):
        raise ValueError("state filename must be a basename")
    return paths.state_dir / name


@contextmanager
def lock(paths: Paths, name: str):
    """Serialize state mutations with at most one second of contention wait."""
    _directory(paths)
    fd = os.open(_file(paths, name), os.O_CREAT | os.O_RDWR, 0o600)
    try:
        os.fchmod(fd, 0o600)
        deadline = time.monotonic() + 1.0
        while True:
            try:
                fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError:
                if time.monotonic() >= deadline:
                    raise TimeoutError("timed out waiting for state lock")
                time.sleep(0.01)
        try:
            yield
        finally:
            fcntl.flock(fd, fcntl.LOCK_UN)
    finally:
        os.close(fd)


def _validate(value: object) -> dict:
    if not isinstance(value, dict) or type(value.get("version")) is not int or value["version"] != 1:
        raise ValueError("unsupported state schema")
    return value


def read(paths: Paths, name: str) -> Optional[dict]:
    try:
        with _file(paths, name).open(encoding="utf-8") as stream:
            return _validate(json.load(stream))
    except FileNotFoundError:
        return None
    except (json.JSONDecodeError, UnicodeError) as exc:
        raise ValueError("invalid state JSON") from exc


def write(paths: Paths, name: str, value: dict) -> None:
    _validate(value)
    target = _file(paths, name)
    _directory(paths)
    fd, temporary = tempfile.mkstemp(prefix="." + name + "-", dir=paths.state_dir)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            os.fchmod(stream.fileno(), 0o600)
            json.dump(value, stream, ensure_ascii=True, allow_nan=False)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, target)
    finally:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass


def pending(paths: Paths) -> list[dict]:
    """Read shared reservation wire data. Caller holds state.lock."""
    value = read(paths, "pending.json")
    if value is None:
        return []
    entries = value.get("pending")
    if not isinstance(entries, list):
        raise ValueError("invalid pending schema")
    requests, sessions = set(), set()
    for entry in entries:
        try:
            request = transcripts.normalize_uuid(entry["request"])
            session = entry["session"]
            sid = transcripts.normalize_uuid(session["session_id"])
            for key in ("source", "target"):
                if entry[key] is not None:
                    transcripts.normalize_uuid(entry[key])
            if (request in requests or sid in sessions or entry["status"] not in
                    ("reserved", "sent", "acknowledged") or not isinstance(entry["launch"], str)
                    or not entry["launch"] or entry["source"] is None
                    or any(not isinstance(session[key], str) or not Path(session[key]).is_absolute()
                           for key in ("cwd", "transcript", "codex_home"))
                    or Path(session["codex_home"]) != paths.codex_home):
                raise ValueError("invalid pending entry")
            requests.add(request)
            sessions.add(sid)
        except (KeyError, TypeError, AttributeError) as exc:
            raise ValueError("invalid pending entry") from exc
    return entries


def save_pending(paths: Paths, entries: list[dict]) -> None:
    """Publish reservations while holding state.lock."""
    write(paths, "pending.json", {"version": 1, "pending": entries})

"""Validate only transcript headers; read conversation text only for display."""
import json
from pathlib import Path
from typing import Optional
from uuid import UUID

from .models import Session


def normalize_uuid(value: str) -> str:
    if not isinstance(value, str):
        raise ValueError("expected UUID string")
    return str(UUID(value))


def validate(path: Path, session_id: str, codex_home: Path, cwd: Path) -> Optional[Session]:
    try:
        sid = normalize_uuid(session_id)
        home = codex_home.resolve()
        if not path.is_absolute() or not cwd.is_absolute():
            return None
        resolved = path.resolve()
        resolved.relative_to((home / "sessions").resolve())
        # Also require the resolved sessions directory to stay in CODEX_HOME.
        resolved.relative_to(home / "sessions")
        with resolved.open(encoding="utf-8") as stream:
            header = json.loads(stream.readline())
        if not isinstance(header, dict) or header.get("type") != "session_meta":
            return None
        payload = header.get("payload")
        if not isinstance(payload, dict):
            return None
        ids = [payload[key] for key in ("id", "session_id") if key in payload]
        if not ids or any(normalize_uuid(value) != sid for value in ids):
            return None
        if payload.get("source") != "cli" or payload.get("originator") != "codex-tui":
            return None
        header_cwd = Path(payload["cwd"])
        if not header_cwd.is_absolute():
            return None
        # The header describes the original launch; resume -C may change cwd.
        return Session(sid, cwd.resolve(), resolved, home)
    except (OSError, ValueError, TypeError, KeyError, RuntimeError):
        return None


def _text(payload: dict) -> str:
    content = payload.get("content")
    metadata = payload.get("internal_chat_message_metadata_passthrough")
    kinds = metadata.get("content_item_kinds") if isinstance(metadata, dict) else None
    has_metadata = "internal_chat_message_metadata_passthrough" in payload
    if isinstance(content, str):
        blocks = [{"type": "input_text", "text": content}]
    elif isinstance(content, list):
        blocks = content
    else:
        return ""
    accepted = []
    for index, block in enumerate(blocks):
        if not isinstance(block, dict) or block.get("type") != "input_text":
            continue
        text = block.get("text")
        if not isinstance(text, str):
            continue
        if has_metadata:
            if not isinstance(kinds, list) or index >= len(kinds) or kinds[index] != "user.text":
                continue
        elif text.lstrip().startswith(("# AGENTS.md instructions", "<environment_context>", "<skill>")):
            continue
        accepted.append(text)
    return " ".join(" ".join(accepted).split())


def title(session: Session) -> str:
    try:
        with session.transcript.open(encoding="utf-8") as stream:
            for line in stream:
                try:
                    item = json.loads(line)
                except ValueError:
                    continue
                if not isinstance(item, dict) or item.get("type") != "response_item":
                    continue
                payload = item.get("payload")
                if not isinstance(payload, dict) or payload.get("type") != "message" or payload.get("role") != "user":
                    continue
                text = _text(payload)
                if text:
                    return text[:120]
    except (OSError, UnicodeError):
        pass
    return session.session_id[:8]

