"""Installed observational dispatcher. Success and every failure emit only {}."""
import json
import os
from pathlib import Path
import signal
import subprocess
import sys
import time

class HookBudgetExpired(BaseException):
    """Overall deadline must bypass ordinary per-handler error isolation."""


class Runner:
    def run(self,argv,*,timeout,stdin=None):
        return subprocess.run(argv,input=stdin,text=True,capture_output=True,timeout=timeout,check=False)


def dispatch(event, settings: dict, runner: Runner, *, restore_metadata=None) -> None:
    from vendor.codex_status import status
    from vendor.codex_status.iterm_support import status_command
    if not status.terminal_id(event.terminal_uuid):
        return
    # Independent, optional handlers are registered by their feature modules.
    if settings.get('notifications') and event.agent in settings.get('notification_agents', ['codex','claude']):
        try:
            try:
                from notifier import handle
            except ImportError:
                from .notifier import handle
            handle(event,settings,runner)
        except Exception:
            pass
    if settings.get('restore') and event.agent == 'codex':
        try:
            try:
                from codex_restore.registry import handle
            except ImportError:
                from .codex_restore.registry import handle
            handle(event,settings,runner,restore_metadata)
        except Exception:
            pass
    if not settings.get('status') or event.agent != 'codex' or not settings.get('it2') or not settings.get('cache'):
        return
    data=Path(settings['cache'])
    if not data.is_absolute():
        return
    data.mkdir(parents=True,exist_ok=True,mode=0o700)
    path=data/(event.terminal_uuid+'.json')
    # Only bounded identifiers/state cross this adapter. No prompt, cwd, arguments,
    # tool output, transcript path reaches the cache. Opaque upstream-compatible tool identities are retained.
    raw={'hook_event_name':event.name,'session_id':event.session_id,
         'turn_id':event.turn_key,'tool_name':event.tool_name,'source':event.source,
         'agent_id':event.agent_id,'tool_key':event.tool_key}
    with status.locked(data/(event.terminal_uuid+'.lock'),0.15):
        previous=status.read_state(path)
        state=status.transition(previous,raw)
        if state is None:
            return
        state.update(revision=previous.get('revision',0)+1,reported=False)
        status.write_state(path,state)
    deadline=time.monotonic()+1.5
    with status.locked(data/(event.terminal_uuid+'.report.lock'),0.2):
        while time.monotonic()<deadline:
            with status.locked(data/(event.terminal_uuid+'.lock'),0.1):
                current=status.read_state(path)
                if current.get('reported'):
                    return
            result=runner.run(status_command(settings['it2'],event.terminal_uuid,current),
                              timeout=min(0.6,max(0.05,deadline-time.monotonic())))
            with status.locked(data/(event.terminal_uuid+'.lock'),0.1):
                latest=status.read_state(path)
                if latest.get('revision')==current.get('revision'):
                    latest['reported']=result.returncode==0
                    status.write_state(path,latest)
                    return


def main(argv: list[str]) -> int:
    # OS-level budget also bounds slow stdin/settings reads and lock contention.
    def expired(*_):
        raise HookBudgetExpired('hook budget')
    old=None
    try:
        old=signal.signal(signal.SIGALRM,expired)
        signal.setitimer(signal.ITIMER_REAL,2.7)
        args=dict(zip(argv[::2],argv[1::2]))
        try:
            from events import normalize
        except ImportError:
            from .events import normalize
        settings_path=Path(args['--settings'])
        settings=json.loads(settings_path.read_text())
        raw=json.loads(sys.stdin.read(2*1024*1024))
        event=normalize(raw,args.get('--agent','codex'),os.environ.get('ITERM_SESSION_ID'))
        if event:
            dispatch(event,settings,Runner(),restore_metadata={key:raw[key] for key in ("session_id","cwd","transcript_path","hook_event_name") if key in raw})
    except (Exception, HookBudgetExpired):
        pass
    finally:
        if old is not None:
            signal.setitimer(signal.ITIMER_REAL,0)
            signal.signal(signal.SIGALRM,old)
    print('{}')
    return 0

if __name__=='__main__':
    sys.exit(main(sys.argv[1:]))

"""Deduplicated observational notices; cache contains only bounded state/IDs."""
from dataclasses import dataclass
from pathlib import Path
import json
import shlex
import subprocess
import sys
import time
try:
    from vendor.codex_status import status
except ImportError:
    from .vendor.codex_status import status
try:
    import claude_notifications
except ImportError:
    from . import claude_notifications

@dataclass(frozen=True)
class Notice:
    agent:str
    terminal_uuid:str
    session_id:str
    token:str
    kind:str

# UUID is an argv item, never inserted into the AppleScript source. Frontmost
# refers to iTerm itself; split panes in the selected tab all count as visible.
CONTEXT_SCRIPT='''on run argv
    set targetID to item 1 of argv
    tell application id "com.googlecode.iterm2"
        set visibleIDs to {}
        if frontmost then
            try
                repeat with s in sessions of current tab of current window
                    set end of visibleIDs to unique ID of s
                end repeat
            on error
                return "unknown"
            end try
        end if
        repeat with w in windows
            repeat with t in tabs of w
                repeat with s in sessions of t
                    if unique ID of s is targetID then return ((targetID is in visibleIDs) as string)
                end repeat
            end repeat
        end repeat
    end tell
    return "unknown"
end run'''

def transition(previous,event):
    if event.agent=='claude':
        state,kind=claude_notifications.transition(previous,event)
    else:
        raw={'hook_event_name':event.name,'session_id':event.session_id,'turn_id':event.turn_key,'tool_name':event.tool_name,'tool_key':event.tool_key,'source':event.source,'agent_id':event.agent_id}
        state=status.transition(previous,raw)
        if state is None:
            return previous,None
        # Upstream pending-work semantics: a main Stop can precede subagent idle.
        reset=(previous.get('session_id')!=event.session_id or event.name in {'UserPromptSubmit','Interrupt','SessionEnd'} or event.name=='SessionStart' and event.source!='compact')
        if reset:
            state.pop('claimed',None);state.pop('input_claims',None);state.pop('completion_pending',None)
        if event.name=='Stop' and previous.get('working'):
            state['completion_pending']=True
        kind=None
        if event.name=='PreToolUse' and event.tool_name in status.INPUT_TOOLS:
            kind='input'
        elif state['status']=='idle' and state.get('completion_pending'):
            kind='complete';state.pop('completion_pending',None)
        # Each waiting request owns its claim. Parallel questions of the same
        # kind must still notify, while retransmission of one question cannot.
        claims=list(state.get('input_claims',[]))
        if event.name=='PostToolUse' and event.tool_key in claims:
            claims.remove(event.tool_key)
        if kind=='input':
            if event.tool_key in claims:
                kind=None
            else:
                claims.append(event.tool_key)
        elif kind=='complete':
            if state.get('claimed')=='complete':
                kind=None
            else:
                state['claimed']='complete'
        state['input_claims']=claims
        # Cache no project/detail strings: these are upstream presentation fields.
        state.pop('project',None);state.pop('detail',None)
    if not kind:
        return state,None
    token=str(time.time_ns())
    state['token']=token
    return state,Notice(event.agent,event.terminal_uuid,event.session_id,token,kind)

def _settings(context):
    if isinstance(context,dict):
        return context
    return {**{k:str(v) for k,v in context.executables.items()},'terminal_notifier':str(context.executables.get('terminal-notifier',''))}

def deliver(notice,context,runner):
    settings=_settings(context)
    paths=[settings.get(k,'') for k in ('terminal_notifier','it2','osascript')]
    if status.terminal_id(notice.terminal_uuid)!=notice.terminal_uuid or not all(Path(p).is_absolute() for p in paths):
        return False
    try:
        result=runner.run([paths[2],'-e',CONTEXT_SCRIPT,notice.terminal_uuid],timeout=0.5)
        if result.returncode or result.stdout.strip()!='false':
            return False
        action=shlex.join([sys.executable,'-B',str(Path(__file__).with_name('focus.py').absolute()),notice.terminal_uuid,paths[1]])
        argv=[paths[0],'-title',notice.agent.capitalize(),'-message',{'input':'Нужен ответ','complete':'Ответ готов','attention':'Нужно внимание'}[notice.kind],'-group',notice.agent+'-'+notice.terminal_uuid,'-execute',action]
        runner.run([sys.executable,'-B',str(Path(__file__).absolute()),'--post',*argv],timeout=0.5)
        return True
    except Exception:
        return False

def handle(event,settings,runner):
    cache=Path(settings.get('notification_cache',''))
    if not cache.is_absolute():
        return
    cache.mkdir(parents=True,exist_ok=True,mode=0o700)
    path=cache/(event.agent+'-'+event.terminal_uuid+'.json')
    with status.locked(path.with_suffix('.lock'),0.1):
        previous=status.read_state(path)
        state,notice=transition(previous,event)
        # Claim before handing off delivery: repeated hooks never resend.
        status.write_state(path,state)
    if notice:
        deliver(notice,settings,runner)

if __name__=='__main__' and len(sys.argv)>2 and sys.argv[1]=='--post':
    # Bounded asynchronous helper. Delivery never holds the hook for app startup.
    try:
        subprocess.Popen([sys.executable,'-B',str(Path(__file__).absolute()),'--worker',*sys.argv[2:]],stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,close_fds=True,start_new_session=True)
    except OSError:
        pass
elif __name__=='__main__' and len(sys.argv)>2 and sys.argv[1]=='--worker':
    try:
        subprocess.run(sys.argv[2:],stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=9,check=False)
    except (OSError,subprocess.SubprocessError):
        pass

#!/usr/bin/env python3
"""Report Codex lifecycle events to iTerm2 without influencing agent decisions."""

import fcntl
from contextlib import contextmanager
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import sys
import tempfile
import time
import unicodedata

# Also support importlib-based embedding by the installer and test tools.
# Local adaptation: transport/settings/notification dispatch lives in runtime/hook.py.
# transition() remains testable without external plugin configuration.


EVENTS = (
    "SessionStart", "UserPromptSubmit", "PreToolUse", "PermissionRequest",
    "PostToolUse", "PreCompact", "PostCompact", "SubagentStart",
    "SubagentStop", "Stop", "Interrupt", "SessionEnd",
)
COLORS = {"working": "#e5a950", "waiting": "#e06c75", "idle": "#98c379", "": ""}
INPUT_TOOLS = {"request_user_input", "request_user_input_async"}


def terminal_id(value):
    """Accept iTerm's w0t0p0:UUID form, but never the implicit active session."""
    candidate = value.rsplit(":", 1)[-1]
    if re.fullmatch(r"[0-9a-fA-F]{8}(?:-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}", candidate):
        return candidate.upper()
    return None


def clean(value, limit=80):
    value = "".join(c for c in str(value or "") if unicodedata.category(c) not in {"Cc", "Cf"} or c in "\n\r\t")
    return " ".join(value.split())[:limit]


def tool_key(event):
    # Local adapter supplies an opaque canonical identity computed in memory.
    # Keep neither prompts nor tool arguments in the status cache.
    if isinstance(event.get("tool_key"), str):
        return event["tool_key"]
    tool = event.get("tool_name")
    payload = event.get("tool_input")
    # PermissionRequest adds a description that PostToolUse omits. The shell or
    # patch command is the stable identifier across those two event shapes.
    if tool in {"Bash", "apply_patch", "Edit", "Write"} and isinstance(payload, dict) and "command" in payload:
        payload = {"command": payload["command"]}
    raw = json.dumps([tool, payload], sort_keys=True)
    return hashlib.sha256(raw.encode()).hexdigest()


def transition(previous, event):
    """Return new state, or None for an event that does not own this terminal."""
    name = event.get("hook_event_name")
    sid = event.get("session_id")
    if name not in EVENTS or not isinstance(sid, str) or not sid:
        return None
    state = dict(previous)
    if state.get("session_id") == sid and state.get("event") == "SessionEnd" and name not in {"SessionStart", "UserPromptSubmit"}:
        return None
    if state.get("session_id") != sid:
        if state and name not in {"SessionStart", "UserPromptSubmit"}:
            return None
        state = {"session_id": sid, "working": False, "agents": [], "waiting": {}}
    if name == "SessionStart" and event.get("source") != "compact":
        state.update(working=False, agents=[], waiting={}, turn_id=None)
    turn = event.get("turn_id")
    if name == "UserPromptSubmit" and isinstance(turn, str):
        state["turn_id"] = turn
    elif name in {"Stop", "Interrupt", "PreCompact", "PostCompact"} and turn and state.get("turn_id") and turn != state["turn_id"]:
        return None
    state["agents"] = list(state.get("agents", []))
    state["waiting"] = dict(state.get("waiting", {}))
    state["project"] = clean(Path(event.get("cwd") or ".").name)
    state["event"] = name
    state["updated_at"] = time.time()
    agent = event.get("agent_id")
    tool = clean(event.get("tool_name"), 50)

    if name == "UserPromptSubmit":
        state.update(working=True, waiting={})
    elif name in {"PreCompact", "PostCompact"}:
        state["working"] = True
    elif name == "SessionStart" and event.get("source") == "compact":
        state["working"] = True
    elif name == "PreToolUse":
        state["working"] = True
        if tool in INPUT_TOOLS:
            add_waiting(state, event, "Input needed")
    elif name == "PermissionRequest":
        add_waiting(state, event, "Approval needed" + (f" ({tool})" if tool else ""))
    elif name == "PostToolUse":
        key = tool_key(event)
        pending = state["waiting"].get(key)
        if isinstance(pending, dict) and pending.get("count", 1) > 1:
            state["waiting"][key] = dict(pending, count=pending["count"] - 1)
        else:
            state["waiting"].pop(key, None)
    elif name == "SubagentStart" and isinstance(agent, str) and agent not in state["agents"]:
        state["agents"].append(agent)
    elif name == "SubagentStop" and agent in state["agents"]:
        state["agents"].remove(agent)
    elif name == "Stop":
        state.update(working=False, waiting={})
    elif name in {"Interrupt", "SessionEnd"}:
        state.update(working=False, waiting={}, agents=[])

    if name == "SessionEnd":
        status, detail = "", ""
    elif state["waiting"]:
        pending = next(iter(state["waiting"].values()))
        description = pending["detail"] if isinstance(pending, dict) else pending
        status, detail = "waiting", "Codex · " + description
    elif state["working"] or state["agents"]:
        status, detail = "working", "Codex · " + state["project"]
        if state["agents"]:
            detail += f" · {len(state['agents'])} subagent(s)"
    else:
        status, detail = "idle", "Codex · " + state["project"]
    state.update(status=status, detail=detail)
    return state


def add_waiting(state, event, detail):
    key = tool_key(event)
    previous = state["waiting"].get(key)
    count = previous.get("count", 1) if isinstance(previous, dict) else (1 if previous else 0)
    state["waiting"][key] = {"detail": detail, "count": count + 1}


@contextmanager
def locked(path, timeout):
    with os.fdopen(os.open(path, os.O_CREAT | os.O_RDWR, 0o600), "w") as lock:
        deadline = time.monotonic() + timeout
        while True:
            try:
                fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError:
                if time.monotonic() >= deadline:
                    raise TimeoutError("Status lock is busy")
                time.sleep(0.01)
        yield


def read_state(path):
    try:
        state = json.loads(path.read_text())
        return state if isinstance(state, dict) else {}
    except (OSError, ValueError):
        return {}


def write_state(path, state):
    fd, tmp = tempfile.mkstemp(prefix="." + path.name, dir=path.parent)
    try:
        with os.fdopen(fd, "w") as output:
            json.dump(state, output)
            output.write("\n")
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            os.unlink(tmp)

